import sqlite3

from payments import gateway, service

KEY_REUSED = {"error": "idempotency key reused"}


def _idempotency_key(request):
    """The Idempotency-Key header, matched case-insensitively; None if missing or empty."""
    for name, value in (request.get("headers") or {}).items():
        if isinstance(name, str) and name.lower() == "idempotency-key":
            if isinstance(value, str) and value.strip():
                return value.strip()
            return None
    return None


def _replay(earlier, customer_id, cents):
    """The response for a request whose key was already used by payment earlier."""
    if earlier["customer_id"] == customer_id and earlier["cents"] == cents:
        return 201, earlier
    return 409, dict(KEY_REUSED)


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}.

    With an Idempotency-Key header, a request whose key was already used for a
    recorded payment charges nothing: the same body gets the earlier 201 again,
    a different body gets 409.
    """
    body = request.get("body") or {}
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    key = _idempotency_key(request)
    if key is not None:
        earlier = service.find_by_idempotency_key(conn, key)
        if earlier is not None:
            return _replay(earlier, customer_id, cents)
    try:
        payment = service.create_payment(conn, customer_id, cents, idempotency_key=key)
    except service.UnknownCustomer:
        return 404, {"error": "no such customer"}
    except gateway.Declined as e:
        conn.rollback()
        return 402, {"error": f"declined: {e}"}
    except sqlite3.IntegrityError:
        # Another request recorded a payment with this key between our lookup
        # and our insert. Roll back our charge and payment and answer as if we
        # had seen theirs first.
        conn.rollback()
        earlier = service.find_by_idempotency_key(conn, key) if key is not None else None
        if earlier is None:
            raise
        return _replay(earlier, customer_id, cents)
    return 201, payment

