import sqlite3

from payments import gateway


class UnknownCustomer(Exception):
    pass


class KeyReused(Exception):
    """An idempotency key was sent again with a different request body."""


def _find_by_key(conn, idempotency_key):
    row = conn.execute("SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
                       (idempotency_key,)).fetchone()
    if row is None:
        return None
    return {"id": row[0], "customer_id": row[1], "cents": row[2], "charge_id": row[3]}


def _replay(payment, customer_id, cents):
    if (payment["customer_id"], payment["cents"]) != (customer_id, cents):
        raise KeyReused()
    return payment


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency_key, a payment already stored under that key is
    returned without charging again, or KeyReused is raised if it was for a
    different customer or amount.
    """
    if idempotency_key is not None:
        existing = _find_by_key(conn, idempotency_key)
        if existing is not None:
            return _replay(existing, customer_id, cents)
    if conn.execute("SELECT 1 FROM customers WHERE id = ?", (customer_id,)).fetchone() is None:
        raise UnknownCustomer(customer_id)
    charge_id = gateway.charge(conn, cents)
    try:
        cur = conn.execute(
            "INSERT INTO payments (customer_id, cents, charge_id, idempotency_key) VALUES (?, ?, ?, ?)",
            (customer_id, cents, charge_id, idempotency_key))
    except sqlite3.IntegrityError:
        # Another request stored this key between our lookup and our insert.
        conn.rollback()
        existing = _find_by_key(conn, idempotency_key) if idempotency_key is not None else None
        if existing is None:
            raise
        return _replay(existing, customer_id, cents)
    conn.commit()
    return {"id": cur.lastrowid, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}

