import sqlite3

from payments import gateway, service


def _idempotency_key(headers):
    """The Idempotency-Key header's value, whatever the case of its name; None if absent."""
    for name, value in headers.items():
        if str(name).lower() == "idempotency-key":
            return value
    return None


def _replay(earlier, customer_id, cents):
    """Answer a request whose key was already used: the stored payment if the body matches, else 409."""
    if (earlier["customer_id"], earlier["cents"]) != (customer_id, cents):
        return 409, {"error": "idempotency key reused"}
    return 201, earlier


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}.

    An optional Idempotency-Key header makes a retry safe: the key is stored with the payment,
    so a repeat with the same key and body gets the stored response and is not charged again.
    """
    body = request.get("body") or {}
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    key = _idempotency_key(request.get("headers") or {})
    if key is not None:
        if type(key) is not str or not key.strip():
            return 400, {"error": "Idempotency-Key must be a non-empty string"}
        earlier = service.find_by_idempotency_key(conn, key)
        if earlier is not None:
            return _replay(earlier, customer_id, cents)
    try:
        payment = service.create_payment(conn, customer_id, cents, key)
    except service.UnknownCustomer:
        return 404, {"error": "no such customer"}
    except gateway.Declined as e:
        conn.rollback()
        return 402, {"error": f"declined: {e}"}
    except sqlite3.IntegrityError:
        # Another request with this key committed between our lookup and our insert, and the
        # unique index refused our row. Rolling back also undoes our gateway_log charge.
        conn.rollback()
        earlier = service.find_by_idempotency_key(conn, key) if key is not None else None
        if earlier is None:
            raise
        return _replay(earlier, customer_id, cents)
    return 201, payment

