from payments import gateway, service

IDEMPOTENCY_HEADER = "idempotency-key"  # HTTP header names are case-insensitive


def _idempotency_key(headers):
    for name, value in headers.items():
        if name.lower() == IDEMPOTENCY_HEADER:
            return value
    return None


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}.

    With an Idempotency-Key header, the key is stored on the payment row. The lookup and
    the charge run under BEGIN IMMEDIATE, so a second request with the same key waits for
    the first to commit and then sees its row instead of charging again.
    """
    body = request.get("body") or {}
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    key = _idempotency_key(request.get("headers") or {})
    if key is None:
        return _create(conn, customer_id, cents, None)
    if not key.strip():
        return 400, {"error": "Idempotency-Key must not be empty"}
    conn.execute("BEGIN IMMEDIATE")
    prior = service.find_by_key(conn, key)
    if prior is not None:
        conn.rollback()
        if (prior["customer_id"], prior["cents"]) == (customer_id, cents):
            return 201, prior
        return 409, {"error": "idempotency key reused"}
    return _create(conn, customer_id, cents, key)


def _create(conn, customer_id, cents, key):
    try:
        payment = service.create_payment(conn, customer_id, cents, key)
    except service.UnknownCustomer:
        conn.rollback()
        return 404, {"error": "no such customer"}
    except gateway.Declined as e:
        conn.rollback()
        return 402, {"error": f"declined: {e}"}
    except Exception:
        conn.rollback()
        raise
    return 201, payment

